import * as NodeChildProcess from "node:child_process";
import * as NodePath from "node:path";
export function launch(repoRoot: string) { return NodeChildProcess.execFileSync(process.execPath, [NodePath.resolve(repoRoot, "child.ts"), "9.9.9-smoke.0", "--root", repoRoot], { encoding: "utf8" }); }
